                if TILE_I * II + i < m:
                    # Compute and store the normalized entry of Q.
                    qik = A[TILE_I * II + i, k] * inv_r
                    Q[TILE_I * II + i, k] = qik

                    # Accumulate the k-th row of R using this qik.
                    # j is innermost → unit-stride accesses to A and R.
                    for j in seq(k + 1, n):
                        R[k, j] += qik * A[TILE_I * II + i, j]

